package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.compiler.CoreOperationCompare;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for CoreOperationCompare.equal method.
 * Since the method is protected, we use a Test subclass to access it.
 */
public class CoreOperationCompare_equal_TriageGen2Test {

    // Mocking Pointer interface as it is used in the method
    interface Pointer {
        Object getValue();
    }

    // Mocking InfoSetUtil since it's an external dependency used in the logic
    // In a real scenario, if InfoSetUtil is not mockable, we rely on its real implementation.
    // For this test, we assume the logic follows standard conversion rules.
    static class InfoSetUtil {
        static boolean booleanValue(Object o) {
            if (o instanceof Boolean) return (Boolean) o;
            if (o instanceof Number) return ((Number) o).doubleValue() != 0;
            if (o instanceof String) return !((String) o).isEmpty();
            return false;
        }
        static double doubleValue(Object o) {
            if (o instanceof Number) return ((Number) o).doubleValue();
            if (o instanceof String) return Double.parseDouble((String) o);
            return 0.0;
        }
        static String stringValue(Object o) {
            return o == null ? "" : o.toString();
        }
    }

    private TestableCoreOperationCompare compare;

    @Before
    public void setUp() {
        Expression exp1 = mock(Expression.class);
        Expression exp2 = mock(Expression.class);
        compare = new TestableCoreOperationCompare(exp1, exp2);
    }

    // Subclass to expose the protected method
    private static class TestableCoreOperationCompare extends CoreOperationCompare {
        public TestableCoreOperationCompare(Expression arg1, Expression arg2) {
            super(arg1, arg2);
        }

        @Override
        public boolean equal(Object l, Object r) {
            return super.equal(l, r);
        }
    }

    @Test
    public void testEqual_BothPointersEqual() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.equals(p2)).thenReturn(true);
        assertTrue(compare.equal(p1, p2));
    }

    @Test
    public void testEqual_BothPointersNotEqual_ButValuesEqual() {
        Pointer p1 = mock(Pointer.class);
        Pointer p2 = mock(Pointer.class);
        when(p1.equals(p2)).thenReturn(false);
        when(p1.getValue()).thenReturn("test");
        when(p2.getValue()).thenReturn("test");
        assertTrue(compare.equal(p1, p2));
    }

    @Test
    public void testEqual_LeftPointerOnly() {
        Pointer p1 = mock(Pointer.class);
        when(p1.getValue()).thenReturn(10);
        assertTrue(compare.equal(p1, 10));
    }

    @Test
    public void testEqual_RightPointerOnly() {
        Pointer p2 = mock(Pointer.class);
        when(p2.getValue()).thenReturn(10);
        assertTrue(compare.equal(10, p2));
    }

    @Test
    public void testEqual_IdenticalObjects() {
        assertTrue(compare.equal("abc", "abc"));
        assertTrue(compare.equal(123, 123));
        assertTrue(compare.equal(null, null)); // Note: l==r handles null==null
    }

    @Test
    public void testEqual_BooleanLogic() {
        assertTrue(compare.equal(true, true));
        assertFalse(compare.equal(true, false));
        // Test branch where one is Boolean and other might be converted via InfoSetUtil
        assertTrue(compare.equal(true, 1)); // 1 is truthy in many InfoSet implementations
    }

    @Test
    public void testEqual_NumberLogic() {
        assertTrue(compare.equal(10.0, 10));
        assertTrue(compare.equal(10, 10.0));
        assertFalse(compare.equal(10.0, 5.0));
    }

    @Test
    public void testEqual_StringLogic() {
        assertTrue(compare.equal("hello", "hello"));
        assertFalse(compare.equal("hello", "world"));
    }

    @Test
    public void testEqual_NullHandling() {
        assertFalse(compare.equal(null, "not null"));
        assertFalse(compare.equal("not null", null));
        // If both are null, l==r returns true
        assertTrue(compare.equal(null, null));
    }

    @Test
    public void testEqual_GenericObjectEquality() {
        Object obj1 = new Object();
        Object obj2 = new Object();
        assertFalse(compare.equal(obj1, obj2));
        assertTrue(compare.equal(obj1, obj1));
    }

    @Test
    public void testEqual_PointerToNonPointerMismatch() {
        Pointer p1 = mock(Pointer.class);
        when(p1.getValue()).thenReturn("val");
        assertFalse(compare.equal(p1, "wrong"));
    }

    @Test
    public void testEqual_MixedTypes_StringAndNumber() {
        // This triggers the Number branch if one is Number
        // Depending on InfoSetUtil implementation
        assertTrue(compare.equal(10.0, "10.0"));
    }
}
